using System.ComponentModel;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public class ApiTools(IHttpClientFactory httpClientFactory, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Fetches data from an external API endpoint.")]
    public async Task<string> FetchData(
        [Description("The relative path to query (e.g. \"users/123\")")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        logger.LogInformation("Calling external API: {Path}", path);

        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerPromptType]
public class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt to summarize the given text.")]
    public static string Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired style: brief, detailed, or bullet-points")] string style = "brief")
    {
        return $"""
            Please summarize the following text in a {style} style.
            Focus on the key points and main ideas.

            Text to summarize:
            {text}
            """;
    }
}

